package com.orderflow.notification.repository;import com.orderflow.notification.domain.*;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface NotificationRepository extends JpaRepository<Notification,UUID>{Page<Notification>findByUserId(UUID user,Pageable p);Page<Notification>findByUserIdAndRead(UUID user,boolean read,Pageable p);Page<Notification>findByUserIdAndType(UUID user,NotificationType type,Pageable p);long countByUserIdAndReadFalse(UUID user);boolean existsByUserIdAndTypeAndSourceEventId(UUID user,NotificationType type,UUID event);@Modifying @Query("update Notification n set n.read=true,n.readAt=:at where n.userId=:user and n.read=false")int markAllRead(@Param("user")UUID user,@Param("at")java.time.Instant at);}
